mapper.select:
select count(1) count
from mqtt_send_log t
where 1=1

    and t.machine_code= #{machineCode}


    and t.cmd_type= #{cmdType}

mapper.delete:
delete from mqtt_send_log
where machine_code= #{machineCode}
and create_time < #{cutoffTime}

mapper.select:
select t.log_id logId,t.business_id businessId,t.machine_code machineCode,
t.car_num carNum,t.cmd_type cmdType,t.topic,t.context,t.remark,
t.create_time createTime
from mqtt_send_log t
where 1=1

    and t.machine_code= #{machineCode}


    and t.cmd_type= #{cmdType}

order by t.create_time desc

    limit #{page}, #{row}
